def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    stage = nb.get('stage') or 'start'
    if p.get('unknown_column_error') or p.get('syntax_error') or (s.get('last_result_was_error') and s.get('last_error_kind') in ('unknown_col', 'syntax')):
        stage = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
    elif p.get('last_result_empty') and not p.get('mutation_task'):
        stage = 'fixing_empty_result'
    elif p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        stage = 'repeated_query_loop'
    elif p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        stage = 'text_numeric_check'
    elif p.get('mutation_task') and p.get('mutation_not_attempted'):
        stage = 'mutation_needs_execution'
    elif p.get('mutation_task') and s.get('mutation_attempted'):
        stage = 'ready_to_commit_candidate'
    elif p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        stage = 'ready_to_commit_candidate'
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Identifier/schema issue: use SHOW TABLES, then DESCRIBE the exact table name with MySQL backticks. Backtick every column used in SELECT, WHERE, ORDER BY, SET, or INSERT lists; do not use double quotes or replace spaces with underscores.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT: inspect sample rows or distinct values for the relevant columns, then relax one predicate at a time. Check exact casing, punctuation, spaces, percent signs, and whether numeric-looking fields are stored as text.'
    elif stage == 'text_numeric_check':
        msg = 'Text numeric check: for least/greatest, ordering, ranking, or aggregation over text columns, cast cleaned numeric values to SIGNED or DECIMAL instead of relying on lexicographic order.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: first DESCRIBE the target table and quote exact identifiers. Preserve requested literal punctuation, spaces, percent signs, and newlines; use CONCAT for string concatenation in MySQL, not the || operator.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Mutation verification: an empty result from INSERT, UPDATE, or DELETE can still mean success. Verify the affected row or count with SELECT, then commit a concise completion answer rather than treating [] as failure.'
    elif stage == 'repeated_query_loop':
        msg = 'Repeated query loop: stop rerunning the same SQL. Change strategy by probing schema, sampling rows, or simplifying predicates to find the mismatch.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    p = ctx.get('predicates') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and (p.get('mutation_not_attempted') or not nb.get('mutation_needs_execution'))):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer list for a SELECT-style task; provide the SQL-derived values in the requested answer shape.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted') and not p.get('candidate_answer_available'):
        return {'kind': 'block_and_prompt', 'message': 'This is a data-changing task, but no INSERT, UPDATE, or DELETE has been executed yet. Perform the mutation and verify it before committing.'}
    return None
